import { useQuery, useInfiniteQuery, keepPreviousData, useMutation } from '@tanstack/react-query';
import { ProductsParams, Products } from '@appTypes/product';
import ApiService from '@services/index';
import API_PATH from '@utils/api.path';
import { IResponse } from '@appTypes/app';
import { queryClient } from '@app/App';

export const searchProducts = async (params: ProductsParams) => {
  const response = await ApiService.get<IResponse<Products[]>>(
    API_PATH.PRODUCTS_SEARCH,
    { params }
  );
  return response?.data;
}

export const transformProductList = (data: Products[]) => {
  return {
    products: data
  }
}

export const useGetProducts = (params: ProductsParams) => {
  return useQuery({
    queryKey: ['search-products'],
    queryFn: () => searchProducts(params),
    select: transformProductList,
    placeholderData: keepPreviousData
  });
}

export const getProductWithInfinite = async (params: ProductsParams, pageParam: number) => {
  const response = await ApiService.get<IResponse<Products[]>>(
    API_PATH.PRODUCTS_SEARCH,
    {
      params: {...params, page: pageParam},
    }
  );
  return response;
}

