export const createProductItem = async (body: Products) => {
  const response = await ApiService.post<IResponse<Products>>(
    API_PATH.PRODUCTS_SEARCH,
    body,
  );
  return response?.data;
}

export const useCreateProduct = () => {
  return useMutation({
    mutationFn: (body: Products) => createProductItem(body),
    onSuccess: (data) => {
      queryClient.invalidateQueries({
        queryKey: ['search-products']
      })
      return data;
    }
  })
}